Task.Run(Outer);                  // из Main: глобальная очередь

void Outer()                      // выполняется в потоке пула P
{
    Task.Run(A);                  // локальная очередь P
    Task.Run(B);                  // локальная очередь P, за A
    Task.Factory.StartNew(C, CancellationToken.None,
        TaskCreationOptions.PreferFairness,
        TaskScheduler.Default);   // глобальная очередь
}
// P закончил Outer → берёт B (с конца своей очереди), потом A.
// Свободный поток Q возьмёт C из глобальной или украдёт A с начала очереди P.

